/// Geometry for a block, or `None` when a plain cube is correct.
pub fn model_for(short_name: &str) -> Option<&'static BlockModel> {
    BLOCK_MODELS
        .binary_search_by_key(&short_name, |(name, _)| name)
        .ok()
        .map(|i| &BLOCK_MODELS[i].1)
}

impl ModelVariant {
    /// True when every condition holds for `props`.
    pub fn matches<'p>(&self, props: &dyn Fn(&str) -> Option<&'p str>) -> bool {
        self.when
            .iter()
            .all(|cond| props(cond.key).is_some_and(|got| cond.values.contains(&got)))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_sorted_for_binary_search() {
        assert!(BLOCK_MODELS.windows(2).all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn cross_plants_are_two_rotated_planes_not_a_cube() {
        for block in ["bush", "amethyst_cluster"] {
            let model = model_for(block).unwrap_or_else(|| panic!("{block} missing"));
            let elements = model.variants[0].elements;
            assert_eq!(elements.len(), 2, "{block} should be a cross");
            for element in elements {
                assert!(element.rotation.is_some());
                assert!((0..3).any(|i| (element.to[i] - element.from[i]).abs() < 0.01));
            }
        }
    }

    #[test]
    fn plain_cubes_are_absent() {
        for block in ["stone", "dirt", "oak_planks"] {
            assert!(model_for(block).is_none(), "{block} needs no entry");
        }
    }

    /// Stairs must resolve to a different orientation per `facing`,
    /// otherwise every stair in a build points the same way.
    #[test]
    fn stairs_orient_by_facing() {
        let model = model_for("oak_stairs").expect("oak_stairs");
        assert!(!model.multipart);
        let pick = |facing: &str| {
            let props = |k: &str| match k {
                "facing" => Some(facing),
                "half" => Some("bottom"),
                "shape" => Some("straight"),
                _ => None,
            };
            model
                .variants
                .iter()
                .find(|v| v.matches(&props))
                .map(|v| v.y_rot)
        };
        let (east, west) = (pick("east"), pick("west"));
        assert!(east.is_some() && west.is_some(), "both facings must match");
        assert_ne!(east, west, "east and west stairs must not share geometry");
    }

    /// A fence is multipart: the post always, plus one side per connection.
    #[test]
    fn fence_combines_post_and_connected_sides() {
        let model = model_for("oak_fence").expect("oak_fence");
        assert!(model.multipart, "fences are multipart");
        let props = |k: &str| match k {
            "north" => Some("true"),
            _ => Some("false"),
        };
        let matched = model.variants.iter().filter(|v| v.matches(&props)).count();
        assert_eq!(matched, 2, "post + north side only");
    }
}
